namespace duckdb {

//! Monotonic clock time point, which is used to measure intervals.
class DUCKDB_API TimePoint {
public:
	TimePoint();

	static TimePoint Tick();

	// Get current monotonic clock time in milliseconds.
	static int64_t GetTickMs();
	// Get two timepoints difference in different units
	static double ElapsedSeconds(const TimePoint &start, const TimePoint &end);
	static int64_t ElapsedMillis(const TimePoint &start, const TimePoint &end);
	static int64_t ElapsedMicros(const TimePoint &start, const TimePoint &end);
	static int64_t ElapsedNanos(const TimePoint &start, const TimePoint &end);

	// Get the elapsed time since the start timepoint in different units
	double ElapsedSeconds() const;
	int64_t ElapsedMillis() const;
	int64_t ElapsedMicros() const;
	int64_t ElapsedNanos() const;

private:
	explicit TimePoint(time_point<steady_clock> value_p);

	time_point<steady_clock> value;
};

} // namespace duckdb



namespace duckdb {

//! Profiler class to measure the elapsed time.
class Profiler {
public:
	//! Start the timer.
	void Start() {
		finished = false;
		ran = true;
		start = TimePoint::Tick();
	}
	//! End the timer.
	void End() {
		end = TimePoint::Tick();
		finished = true;
	}
	void Reset() {
		finished = false;
		ran = false;
	}

	//! Returns the elapsed time in seconds.
	//! If ran is false, it returns 0.
	//! If End() has been called, it returns the total elapsed time,
	//! otherwise, returns how far along the timer is right now.
	double Elapsed() const {
		if (!ran) {
			return 0;
		}
		int64_t elapsed_nanos = 0;
		if (finished) {
			elapsed_nanos = TimePoint::ElapsedNanos(start, end);
		} else {
			elapsed_nanos = start.ElapsedNanos();
		}
		return static_cast<double>(elapsed_nanos) / 1e9;
	}

	idx_t ElapsedNanos() const {
		if (!ran) {
			return 0;
		}
		if (finished) {
			return static_cast<idx_t>(TimePoint::ElapsedNanos(start, end));
		}
		return static_cast<idx_t>(start.ElapsedNanos());
	}

private:
	TimePoint start;
	TimePoint end;
	bool finished = false;
	bool ran = false;
};

} // namespace duckdb

