struct StorageVersionInfo {
	// When the default storage version has to be updated, do it here
	static constexpr StorageVersion DEFAULT_STORAGE_VERSION_INFO = StorageVersion::V2_0_0;

	const char *version_name;
	StorageVersion storage_version;

	static string GetStorageVersionString(const StorageVersion &version);

	static constexpr StorageVersion GetStorageVersionDefault() {
		return DEFAULT_STORAGE_VERSION_INFO;
	};

	static constexpr idx_t GetStorageVersionDefaultInt() {
		return static_cast<idx_t>(DEFAULT_STORAGE_VERSION_INFO);
	};

	static constexpr StorageVersion Invalid() {
		return StorageVersion::INVALID;
	};

	static constexpr idx_t InvalidStorageVersionInt() {
		return static_cast<idx_t>(StorageVersion::INVALID);
	};
};

struct SerializationVersionInfo {
	const char *version_name;
	SerializationVersionDeprecated storage_version;

	static constexpr uint64_t GetSerializationVersionValue(SerializationVersionDeprecated version) {
		return static_cast<uint64_t>(version);
	}

	static constexpr uint64_t Invalid() {
		return GetSerializationVersionValue(SerializationVersionDeprecated::INVALID);
	};
};

