	CreateTypeInfo();
	CreateTypeInfo(string name_p, LogicalType type_p, bind_logical_type_function_t bind_function_p = nullptr);
	CreateTypeInfo(string name_p, LogicalType type_p, TypeConstructorSet constructors_p);

